"use client";

import CssBaseline from '@mui/material/CssBaseline';
import Container from '@mui/material/Container';
import AppTheme from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/AppTheme';
import AppAppBar from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/blog/components/AppAppBar';
import MainContent from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/blog/components/MainContent';
import Latest from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/blog/components/Latest';
import Footer from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/blog/components/Footer';

export default function Blog(props: { disableCustomTheme?: boolean }) {
  return (
    <AppTheme {...props}>
      <CssBaseline enableColorScheme />

      <AppAppBar />
      <Container
        maxWidth="lg"
        component="main"
        sx={{ display: 'flex', flexDirection: 'column', my: 16, gap: 4 }}
      >
        <MainContent />
        <Latest />
      </Container>
      <Footer />
    </AppTheme>
  );
}

"use client";

import * as React from 'react';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import type { ThemeOptions } from '@mui/material/styles';
import { inputsCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/inputs';
import { dataDisplayCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/dataDisplay';
import { feedbackCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/feedback';
import { navigationCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/navigation';
import { surfacesCustomizations } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/customizations/surfaces';
import { colorSchemes, typography, shadows, shape } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/themePrimitives';

interface AppThemeProps {
  children: React.ReactNode;
  /**
   * This is for the docs site. You can ignore it or remove it.
   */
  disableCustomTheme?: boolean;
  themeComponents?: ThemeOptions['components'];
}

export default function AppTheme(props: AppThemeProps) {
  const { children, disableCustomTheme, themeComponents } = props;
  const theme = React.useMemo(() => {
    return disableCustomTheme
      ? {}
      : createTheme({
          // For more details about CSS variables configuration, see https://mui.com/material-ui/customization/css-theme-variables/configuration/
          cssVariables: {
            colorSchemeSelector: 'data-mui-color-scheme',
            cssVarPrefix: 'template',
          },
          colorSchemes, // Recently added in v6 for building light & dark mode app, see https://mui.com/material-ui/customization/palette/#color-schemes
          typography,
          shadows,
          shape,
          components: {
            ...inputsCustomizations,
            ...dataDisplayCustomizations,
            ...feedbackCustomizations,
            ...navigationCustomizations,
            ...surfacesCustomizations,
            ...themeComponents,
          },
        });
  }, [disableCustomTheme, themeComponents]);
  if (disableCustomTheme) {
    return <React.Fragment>{children}</React.Fragment>;
  }
  return (
    <ThemeProvider theme={theme} disableTransitionOnChange>
      {children}
    </ThemeProvider>
  );
}

"use client";

import { alpha, Theme, Components } from '@mui/material/styles';
import { outlinedInputClasses } from '@mui/material/OutlinedInput';
import { svgIconClasses } from '@mui/material/SvgIcon';
import { toggleButtonGroupClasses } from '@mui/material/ToggleButtonGroup';
import { toggleButtonClasses } from '@mui/material/ToggleButton';
import CheckBoxOutlineBlankRoundedIcon from '@mui/icons-material/CheckBoxOutlineBlankRounded';
import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import RemoveRoundedIcon from '@mui/icons-material/RemoveRounded';
import { gray, brand } from '@/components/rendyn-libraries/mui/upstream/data/material/getting-started/templates/shared-theme/themePrimitives';

/* eslint-disable import/prefer-default-export */
export const inputsCustomizations: Components<Theme> = {
  MuiButtonBase: {
    defaultProps: {
      disableTouchRipple: true,
      disableRipple: true,
    },
    styleOverrides: {
      root: ({ theme }) => ({
        boxSizing: 'border-box',
        transition: 'all 100ms ease-in',
        '&:focus-visible': {
          outline: `3px solid ${alpha(theme.palette.primary.main, 0.5)}`,
          outlineOffset: '2px',
        },
